/* Explicit developer measurement UI. Absent from normal visits. Same harness before/after. */
function installProfile38(B,scene,engine,camera,rendering,world,controls){
 if(!new URLSearchParams(location.search).has('profile38'))return;
 // BUILD093: diagnostics only. Marks are navigation-relative, not a claim of browser TTI.
 function startup93(){
  const marks=performance.getEntriesByType('mark').filter(e=>e.name.startsWith('3nu:')).map(e=>({phase:e.name.slice(4),ms:+e.startTime.toFixed(2)}));
  const resources=performance.getEntriesByType('resource').map(e=>({path:new URL(e.name,location.href).pathname,type:e.initiatorType,startMs:+e.startTime.toFixed(2),durationMs:+e.duration.toFixed(2),transferBytes:e.transferSize,encodedBytes:e.encodedBodySize,decodedBytes:e.decodedBodySize}));
  return{marks,resources,transferBytes:resources.reduce((n,r)=>n+r.transferBytes,0),decodedBytes:resources.reduce((n,r)=>n+r.decodedBytes,0),note:'ResourceTiming may report zero for cached/restricted entries; no GPU memory estimate.'};
 }
 const inst=new B.SceneInstrumentation(scene);inst.captureFrameTime=true;inst.captureRenderTime=true;inst.captureActiveMeshesEvaluationTime=true;
 const panel=document.createElement('aside');panel.id='profile38';panel.style.cssText='position:fixed;bottom:24px;left:12px;z-index:90;background:#fffffff2;padding:10px;width:440px;font:12px system-ui;max-height:260px;overflow:auto';
 panel.innerHTML='<label>측정 장면 <select aria-label="측정 장면"><option value="facade56-220">종합교육연구동</option><option value="facade54-86">치의학 외관</option><option value="facade53-71-2">스포츠센터 외관</option><option value="pond47-oblique">자하연 R2 사선</option><option value="moving47">자하연 데크 왕복</option><option value="theater48-oblique">풍산마당 사선</option><option value="moving48">공연장 외곽 왕복</option><option value="humanities45-oblique">humanities45-oblique</option><option value="landmark44-gate">landmark44-gate</option><option value="landmark44-museum">landmark44-museum</option><option value="landmark44-pond">landmark44-pond</option><option value="landmark44-stadium">landmark44-stadium</option><option value="moving44">미술관 하부 왕복</option><option value="civic42-culture">civic42-culture</option><option value="civic42-admin">civic42-admin</option><option value="civic42-side">civic42-side</option><option value="finish41-1">finish41-1</option><option value="finish41-2">finish41-2</option><option value="finish41-3">finish41-3</option><option value="b40-310">b40-310</option><option value="b40-311">b40-311</option><option value="b40-312">b40-312</option><option value="b40-313">b40-313</option><option value="b40-314">b40-314</option><option value="b40-campus">b40-campus</option><option value="C">C central stairs</option><option value="D">D student approach</option><option value="E">E middle court</option><option value="facade">관정관 근접</option><option value="moving">계단·정원 이동</option><option value="campus">캠퍼스 전경</option><option value="photo1">사진1 광장</option><option value="photo2">사진2 계단 끝</option></select></label> <button>측정 시작</button><pre id="profile38status" style="white-space:pre-wrap"></pre>';
 document.body.appendChild(panel);const select=panel.querySelector('select'),status=panel.querySelector('pre');let run=null,last=performance.now(),samples=[],output={state:'ready',startup:startup93()},shown=0,pickMs=0,pickCalls=0,moveMs=0;
 const originalPick=scene.pickWithRay.bind(scene);scene.pickWithRay=function(...args){const t=performance.now();try{return originalPick(...args);}finally{pickMs+=performance.now()-t;pickCalls++;}};
 const originalMove=world.move;world.move=function(...args){const t=performance.now();try{return originalMove(...args);}finally{moveMs+=performance.now()-t;}};
 const summary=arr=>{const a=arr.slice().sort((a,b)=>a-b);return{mean:a.reduce((s,x)=>s+x,0)/(a.length||1),p50:a[Math.floor(a.length*.5)]??null,p95:a[Math.floor(a.length*.95)]??null,p99:a[Math.floor(a.length*.99)]??null,max:a.at(-1)??null};};
 select.onchange=()=>controls.view(select.value);
 panel.querySelector('button').onclick=()=>{controls.view(select.value);if((select.value==='moving'||select.value==='moving44'||select.value==='moving48'||select.value==='moving47'))controls.walk();samples=[];run={scene:select.value,started:performance.now(),warmupMs:5000,durationMs:15000};output={state:'warming',scene:select.value};last=performance.now();};
 scene.onAfterRenderObservable.add(()=>{const now=performance.now(),dt=now-last;last=now;
 if(run){const elapsed=now-run.started;if(elapsed>=run.warmupMs&&elapsed<run.warmupMs+run.durationMs){samples.push({dt,draws:inst.drawCallsCounter.current,triangles:scene.getActiveIndices()/3,active:scene.getActiveMeshes().length,renderMs:inst.renderTimeCounter.current,frameCpuMs:inst.frameTimeCounter.current,activeEvaluationMs:inst.activeMeshesEvaluationTimeCounter.current,pickMs,pickCalls,moveMs});output={state:'measuring',scene:run.scene,elapsedMs:Math.round(elapsed-run.warmupMs),samples:samples.length};}
 if(elapsed>=run.warmupMs+run.durationMs){const a=scene.getActiveMeshes(),meshes=a.data.slice(0,a.length);const inventory=meshes.map(m=>({name:m.name,triangles:m.getTotalIndices()/3*Math.max(1,m.thinInstanceCount||1),instances:m.thinInstanceCount||0})).sort((a,b)=>b.triangles-a.triangles);
 output={state:'complete',scene:run.scene,startup:startup93(),conditions:{viewport:[innerWidth,innerHeight],devicePixelRatio,quality:rendering.metrics(),warmupMs:run.warmupMs,durationMs:run.durationMs,eye:camera.position.asArray(),target:camera.getTarget().asArray()},frames:samples.length,frameMs:summary(samples.map(q=>q.dt)),drawCalls:summary(samples.map(q=>q.draws)),triangles:summary(samples.map(q=>q.triangles)),renderMs:summary(samples.map(q=>q.renderMs)),frameCpuMs:summary(samples.map(q=>q.frameCpuMs)),activeEvaluationMs:summary(samples.map(q=>q.activeEvaluationMs)),pickMs:summary(samples.map(q=>q.pickMs)),moveMs:summary(samples.map(q=>q.moveMs)),over50ms:samples.filter(q=>q.dt>50).length,over100ms:samples.filter(q=>q.dt>100).length,jsHeapBytes:performance.memory?.usedJSHeapSize??null,gpuMemoryBytes:null,gpuTimeMs:null,inventory:inventory.slice(0,15),totalMeshes:scene.meshes.length,totalGeometries:scene.geometries.length,totalMaterials:scene.materials.length,treeAudit:scene.metadata?.trees38??null};run=null;controls.stop();}}
 pickMs=0;pickCalls=0;moveMs=0;if(now-shown>400){status.textContent=JSON.stringify(output);shown=now;}
 });
}
